module alu(
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output flag
    );

parameter ADD = 6'b100000;
parameter ADDU = 6'b100001;
parameter SUB = 6'b100010;
parameter SUBU = 6'b100011;
parameter AND = 6'b100100;
parameter OR = 6'b100101;
parameter XOR = 6'b100110;
parameter NOR = 6'b100111;
parameter SLT = 6'b101010;
parameter SLTU = 6'b101011;
parameter SLL = 6'b000000;
parameter SRL = 6'b000010;
parameter SRA = 6'b000011;
parameter SLLV = 6'b000100;
parameter SRLV = 6'b000110;
parameter SRAV = 6'b000111;
parameter LUI = 6'b001111;

reg [31:0] a_reg;
reg [31:0] b_reg;
reg [31:0] res;
reg flag_reg;

always@(*) begin
    a_reg = a;
    b_reg = b;
end

always@(*) begin
    case(aluc)
        ADD: begin
            res = a_reg + b_reg;
        end
        ADDU: begin
            res = a_reg + b_reg;
        end
        SUB: begin
            res = a_reg - b_reg;
        end
        SUBU: begin
            res = a_reg - b_reg;
        end
        AND: begin
            res = a_reg & b_reg;
        end
        OR: begin
            res = a_reg | b_reg;
        end
        XOR: begin
            res = a_reg ^ b_reg;
        end
        NOR: begin
            res = ~(a_reg | b_reg);
        end
        SLT: begin
            if (a_reg < b_reg) begin
                res = 32'b1;
            end
            else begin
                res = 32'b0;
            end
        end
        SLTU: begin
            if (a_reg < b_reg) begin
                res = 32'b1;
            end
            else begin
                res = 32'b0;
            end
        end
        SLL: begin
            res = b_reg << a_reg[4:0];
        end
        SRL: begin
            res = b_reg >> a_reg[4:0];
        end
        SRA: begin
            res = b_reg >>> a_reg[4:0];
        end
        SLLV: begin
            res = b_reg << a_reg;
        end
        SRLV: begin
            res = b_reg >> a_reg;
        end
        SRAV: begin
            res = b_reg >>> a_reg;
        end
        LUI: begin
            res = {16'b0, a_reg};
        end
        default: begin
            res = 32'b0;
        end
    endcase
end

assign r = res;
assign flag = (aluc == SLT || aluc == SLTU)?((aluc == SLT)?(a_reg < b_reg):(a_reg < b_reg)):0;
assign zero = (res == 32'b0)?1:0;
assign carry = (aluc == ADD || aluc == ADDU || aluc == SUB || aluc == SUBU)?((aluc == ADD || aluc == ADDU)?(a_reg[31] ^ b_reg[31] ^ res[31]):(a_reg[31] ^ b_reg[31] ^ (res[31] ^ 1))):0;
assign overflow = (aluc == ADD || aluc == ADDU)?((a_reg[31] == b_reg[31] && a_reg[31] != res[31])?1:0):(aluc == SUB || aluc == SUBU)?((a_reg[31] != b_reg[31] && a_reg[31] != res[31])?1:0):0;
assign negative = res[31]?1:0;

endmodule
